The core is the textbook CLRS B-tree algorithm (chapters 18.2–18.3) with `t = 4`, operating on `dict` nodes `{'keys': [...], 'children': [...]}` where leaves have `children == []`. Insertion splits full nodes (7 keys → median moves up) on the way down, growing the root when needed. Deletion follows CLRS B-TREE-DELETE: replace-from-sibling on internal nodes (pred/succ), borrow from a sibling before merging on underflow, and shrink the root if it empties. Keys are kept unique: duplicate inserts and deletes of missing keys are no-ops.

```python
T = 4
MIN_KEYS = T - 1      # 3
MAX_KEYS = 2 * T - 1  # 7

def _empty():
    return {'keys': [], 'children': []}

def _norm(root):
    if root is None or not isinstance(root, dict):
        return _empty()
    if 'keys' not in root:
        root['keys'] = []
    if 'children' not in root:
        root['children'] = []
    return root

# ---------------- insertion ----------------
def _split_child(parent, i):
    child = parent['children'][i]
    median = child['keys'][T - 1]
    right = {'keys': child['keys'][T:], 'children': child['children'][T:]}
    child['keys'] = child['keys'][:T - 1]
    child['children'] = child['children'][:T]
    parent['keys'].insert(i, median)
    parent['children'].insert(i + 1, right)

def _insert_nonfull(node, key):
    keys = node['keys']
    i = 0
    while i < len(keys) and key > keys[i]:
        i += 1
    if i < len(keys) and keys[i] == key:
        return  # duplicate -> keep keys unique
    if not node['children']:
        keys.insert(i, key)
        return
    if len(node['children'][i]['keys']) == MAX_KEYS:
        _split_child(node, i)
        if key > node['keys'][i]:
            i += 1
        elif key == node['keys'][i]:
            return  # median moved up equals key
    _insert_nonfull(node['children'][i], key)

def insert(root, key):
    root = _norm(root)
    if len(root['keys']) == MAX_KEYS:
        new_root = {'keys': [], 'children': [root]}
        _split_child(new_root, 0)
        root = new_root
    _insert_nonfull(root, key)
    return root

# ---------------- search ----------------
def search(root, key):
    root = _norm(root)
    node = root
    while True:
        keys = node['keys']
        i = 0
        while i < len(keys) and key > keys[i]:
            i += 1
        if i < len(keys) and keys[i] == key:
            return True
        if not node['children']:
            return False
        node = node['children'][i]

# ---------------- deletion ----------------
def _subtree_max(node):
    while node['children']:
        node = node['children'][-1]
    return node['keys'][-1]

def _subtree_min(node):
    while node['children']:
        node = node['children'][0]
    return node['keys'][0]

def _merge(x, i):
    left, right = x['children'][i], x['children'][i + 1]
    left['keys'].append(x['keys'][i])
    left['keys'].extend(right['keys'])
    left['children'].extend(right['children'])
    del x['children'][i + 1]
    del x['keys'][i]

def _borrow_left(x, i):
    child, sibling = x['children'][i], x['children'][i - 1]
    child['keys'].insert(0, x['keys'][i - 1])
    x['keys'][i - 1] = sibling['keys'].pop()
    if sibling['children']:
        child['children'].insert(0, sibling['children'].pop())

def _borrow_right(x, i):
    child, sibling = x['children'][i], x['children'][i + 1]
    child['keys'].append(x['keys'][i])
    x['keys'][i] = sibling['keys'].pop(0)
    if sibling['children']:
        child['children'].append(sibling['children'].pop(0))

def _delete(node, key):
    keys, children = node['keys'], node['children']
    i = 0
    while i < len(keys) and key > keys[i]:
        i += 1
    if not children:                       # leaf
        if i < len(keys) and keys[i] == key:
            del keys[i]
        return
    if i < len(keys) and keys[i] == key:   # key in internal node
        if len(children[i]['keys']) >= T:          # 2a: predecessor
            pred = _subtree_max(children[i])
            keys[i] = pred
            _delete(children[i], pred)
        elif len(children[i + 1]['keys']) >= T:    # 2b: successor
            succ = _subtree_min(children[i + 1])
            keys[i] = succ
            _delete(children[i + 1], succ)
        else:                                     # 2c: merge
            _merge(node, i)
            _delete(children[i], key)
    else:                                    # descend, repair underflow first
        if len(children[i]['keys']) == MIN_KEYS:
            if i > 0 and len(children[i - 1]['keys']) >= T:
                _borrow_left(node, i)
            elif i < len(children) - 1 and len(children[i + 1]['keys']) >= T:
                _borrow_right(node, i)
            else:
                if i > 0:
                    _merge(node, i - 1); i -= 1
                else:
                    _merge(node, i)
        _delete(children[i], key)

def delete(root, key):
    root = _norm(root)
    if root['keys'] or root['children']:
        _delete(root, key)
        while not root['keys'] and root['children']:   # shrink empty root
            root = root['children'][0]
    return root

# ---------------- traversal ----------------
def to_list(root):
    root = _norm(root)
    result = []
    def walk(node):
        for i in range(len(node['keys'])):
            if node['children']:
                walk(node['children'][i])
            result.append(node['keys'][i])
        if node['children']:
            walk(node['children'][-1])
    walk(root)
    return result
